module.exports = Object.assign ( run, {
options: ['--as'],
staticCompletions: () => ({
  '--as': ['json', 'yaml'],
}),
help: `
# SYNOPSIS

    *cds bindings* <code snippet>

    Reads and prints the information about locally running CAP services
    from ~/.cds/services.json file. This is particularly useful for agents
    to access that information without requesting for approval to directly
    accessing the file in the user's home directory.

# EXAMPLES

    cds bindings
    cds bindings --as json
`})

const cds = require('../lib/cds')
const YAML = cds.utils.yaml

// support the like of cds -e "<...>" as in node.js --> pretty helpful for quick test setups
async function run (_, { as }) {
  const { inspect } = require('util'); inspect.defaultOptions = { depth: null, colors: true }
  const bindings = await cds.service.bindings
  return console.log ((
    as === 'yaml' ? YAML.stringify(bindings) :
    as === 'json' ? JSON.stringify(bindings,null,2) :
    !process.stdout.isTTY ? YAML.stringify(bindings) :
    bindings
  ))
}
